@import url('https://fonts.googleapis.com/css2?family=Roboto:ital,wght@0,400;0,500;0,700;1,400&display=swap');
@import 'tailwindcss';

@theme {
  --font-sans: 'Google Sans', 'Roboto', ui-sans-serif, system-ui, sans-serif;
  --color-canvas: var(--canvas);
  --color-panel: var(--panel);
  --color-panel-alt: var(--panel-alt);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);
  --color-ink-4: var(--ink-4);
  --color-line: var(--line);
  --color-hov: var(--hov);
  --color-selected: var(--selected);
  --color-selected-soft: var(--selected-soft);
  --color-accent: var(--accent);
  --color-compose: var(--compose);
  --color-compose-ink: var(--compose-ink);
  --color-star: var(--star);
  --color-search: var(--search);
  --color-danger: var(--danger);
  --color-scrim: var(--scrim);
  --color-chip: var(--chip);
  --shadow-e1: var(--shadow-e1);
  --shadow-e2: var(--shadow-e2);
  --shadow-e3: var(--shadow-e3);
}

:root {
  --canvas: #f6f8fc;
  --panel: #ffffff;
  --panel-alt: #f0f4f9;
  --ink: #1f1f1f;
  --ink-2: #444746;
  --ink-3: #5f6368;
  --ink-4: #80868b;
  --line: #e1e3e1;
  --hov: #e7e8ee;
  --selected: #c2e7ff;
  --selected-soft: #d3e3fd;
  --accent: #0b57d0;
  --compose: #c2e7ff;
  --compose-ink: #001d35;
  --star: #f4b400;
  --search: #eaf1fb;
  --danger: #b3261e;
  --scrim: rgb(31 31 31 / 0.4);
  --chip: #e8eaed;
  --shadow-e1: 0 1px 2px 0 rgb(60 64 67 / 0.3), 0 1px 3px 1px rgb(60 64 67 / 0.15);
  --shadow-e2: 0 2px 6px 2px rgb(60 64 67 / 0.15), 0 1px 2px 0 rgb(60 64 67 / 0.3);
  --shadow-e3: 0 4px 8px 3px rgb(60 64 67 / 0.15), 0 1px 3px 0 rgb(60 64 67 / 0.3);
  color-scheme: light;
}

[data-theme='dark'] {
  --canvas: #1f1f1f;
  --panel: #2d2e30;
  --panel-alt: #3c4043;
  --ink: #e3e3e3;
  --ink-2: #c4c7c5;
  --ink-3: #9aa0a6;
  --ink-4: #80868b;
  --line: #3c4043;
  --hov: #3c4043;
  --selected: #004a77;
  --selected-soft: #0842a0;
  --accent: #a8c7fa;
  --compose: #8ab4f8;
  --compose-ink: #062e6f;
  --star: #f4b400;
  --search: #3c4043;
  --danger: #f2b8b5;
  --scrim: rgb(0 0 0 / 0.55);
  --chip: #3c4043;
  --shadow-e1: 0 1px 2px 0 rgb(0 0 0 / 0.5), 0 1px 3px 1px rgb(0 0 0 / 0.3);
  --shadow-e2: 0 2px 6px 2px rgb(0 0 0 / 0.4), 0 1px 2px 0 rgb(0 0 0 / 0.5);
  --shadow-e3: 0 4px 8px 3px rgb(0 0 0 / 0.4), 0 1px 3px 0 rgb(0 0 0 / 0.5);
  color-scheme: dark;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
}

button,
input,
textarea,
select {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

* {
  box-sizing: border-box;
}

::selection {
  background: var(--selected);
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.mail-body p {
  margin: 0 0 0.85em;
}
.mail-body p:last-child {
  margin-bottom: 0;
}
.mail-body blockquote {
  margin: 0.75em 0 0;
  padding-left: 12px;
  border-left: 2px solid var(--line);
  color: var(--ink-3);
}
.mail-body a {
  color: var(--accent);
}

.compose-editor:empty::before {
  content: attr(data-placeholder);
  color: var(--ink-4);
}

.scrollbar-thin {
  scrollbar-width: thin;
  scrollbar-color: var(--ink-4) transparent;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes slide-up {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes drawer-in {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(0);
  }
}

.anim-fade {
  animation: fade-in 160ms cubic-bezier(0.2, 0, 0, 1);
}
.anim-up {
  animation: slide-up 180ms cubic-bezier(0.2, 0, 0, 1);
}
.anim-drawer {
  animation: drawer-in 200ms cubic-bezier(0.2, 0, 0, 1);
}

@media print {
  .no-print {
    display: none !important;
  }
  .print-root,
  .print-root * {
    background: white !important;
    color: black !important;
    box-shadow: none !important;
  }
}

