            data-menu={id}
            role="menu"
            className="anim-up fixed z-[120] overflow-hidden rounded-xl bg-panel py-1 shadow-e3"
            style={{ top: pos.top, left: pos.left, width }}
          >
            {children(() => setOpen(false))}
          </div>,
